import React, { useState } from 'react'

import {
    Form,
    Button,
    Card,
    InputGroup
} from 'react-bootstrap'

import {
    useDispatch,
    useSelector
} from 'react-redux'

import {
    createUserAddress,
    getAllAddress
} from '../actions/userActions'

import {
    CREATE_USER_ADDRESS_RESET
} from '../constants'

import Message from './Message'


const CreateAddressComponent = ({ toggleCreateAddress }) => {

    const dispatch = useDispatch()


    // =========================================
    // FORM STATE
    // =========================================

    const [name, setName] = useState("")
    const [phoneNumber, setPhoneNumber] = useState("")
    const [pinCode, setPinCode] = useState("")
    const [houseNumber, setHouseNumber] = useState("")
    const [landmark, setLandmark] = useState("")
    const [city, setCity] = useState("")
    const [state, setState] = useState("")


    // =========================================
    // CREATE ADDRESS REDUCER
    // =========================================

    const createUserAddressReducer = useSelector(
        state => state.createUserAddressReducer
    )

    const {
        loading,
        success: addressCreationSuccess,
        error: errorCreatingAddress
    } = createUserAddressReducer


    // =========================================
    // SUBMIT ADDRESS
    // =========================================

    const addressSubmitHandler = (e) => {

        e.preventDefault()

        const addressData = {
            name: name,
            phone_number: phoneNumber,
            pin_code: pinCode,
            house_no: houseNumber,
            landmark: landmark,
            city: city,
            state: state
        }

        dispatch(
            createUserAddress(addressData)
        )
    }


    // =========================================
    // ADDRESS CREATED SUCCESSFULLY
    // =========================================

    if (addressCreationSuccess) {

        alert("Address successfully created.")

        dispatch({
            type: CREATE_USER_ADDRESS_RESET
        })

        dispatch(
            getAllAddress()
        )

        toggleCreateAddress()
    }


    // =========================================
    // RETURN
    // =========================================

    return (

        <div>

            <p className="text-center text-info">
                <em>New Address</em>
            </p>


            {/* =========================================
                ERROR MESSAGE
            ========================================= */}

            {errorCreatingAddress && (

                <Message variant="danger">
                    {errorCreatingAddress}
                </Message>

            )}


            {/* =========================================
                ADDRESS FORM
            ========================================= */}

            <Card
                className="mx-auto mb-4"
                style={{
                    width: "50%",
                    border: "1px solid",
                    borderColor: "#C6ACE7"
                }}
            >

                <Card.Body>

                    <Form onSubmit={addressSubmitHandler}>


                        {/* =========================================
                            NAME
                        ========================================= */}

                        <Form.Group controlId="name">

                            <Form.Label>
                                Name
                            </Form.Label>

                            <Form.Control
                                autoFocus
                                required
                                type="text"
                                placeholder="Enter your name"
                                value={name}
                                onChange={(e) =>
                                    setName(e.target.value)
                                }
                            />

                        </Form.Group>


                        {/* =========================================
                            PHONE NUMBER
                        ========================================= */}

                        <Form.Group controlId="phoneNumber">

                            <Form.Label>
                                Phone Number
                            </Form.Label>

                            <InputGroup>

                                <InputGroup.Text>
                                    +91
                                </InputGroup.Text>

                                <Form.Control
                                    required
                                    type="text"
                                    placeholder="Phone number"
                                    pattern="[0-9]{10}"
                                    maxLength="10"
                                    value={phoneNumber}
                                    onChange={(e) =>
                                        setPhoneNumber(e.target.value)
                                    }
                                />

                            </InputGroup>

                        </Form.Group>


                        {/* =========================================
                            PIN CODE
                        ========================================= */}

                        <Form.Group controlId="pinCode">

                            <Form.Label>
                                Pin Code
                            </Form.Label>

                            <Form.Control
                                required
                                type="text"
                                placeholder="Pin code"
                                pattern="[0-9]{6}"
                                maxLength="6"
                                value={pinCode}
                                onChange={(e) =>
                                    setPinCode(e.target.value)
                                }
                            />

                        </Form.Group>


                        {/* =========================================
                            HOUSE NUMBER
                        ========================================= */}

                        <Form.Group controlId="houseNumber">

                            <Form.Label>
                                House No. / Address
                            </Form.Label>

                            <Form.Control
                                required
                                type="text"
                                placeholder="House number / Address"
                                value={houseNumber}
                                onChange={(e) =>
                                    setHouseNumber(e.target.value)
                                }
                            />

                        </Form.Group>


                        {/* =========================================
                            LANDMARK
                        ========================================= */}

                        <Form.Group controlId="landmark">

                            <Form.Label>
                                Landmark
                            </Form.Label>

                            <Form.Control
                                type="text"
                                placeholder="Landmark"
                                value={landmark}
                                onChange={(e) =>
                                    setLandmark(e.target.value)
                                }
                            />

                        </Form.Group>


                        {/* =========================================
                            CITY
                        ========================================= */}

                        <Form.Group controlId="city">

                            <Form.Label>
                                City
                            </Form.Label>

                            <Form.Control
                                required
                                type="text"
                                placeholder="City"
                                value={city}
                                onChange={(e) =>
                                    setCity(e.target.value)
                                }
                            />

                        </Form.Group>


                        {/* =========================================
                            STATE
                        ========================================= */}

                        <Form.Group controlId="state">

                            <Form.Label>
                                State
                            </Form.Label>

                            <Form.Control
                                required
                                type="text"
                                placeholder="State"
                                value={state}
                                onChange={(e) =>
                                    setState(e.target.value)
                                }
                            />

                        </Form.Group>


                        {/* =========================================
                            SAVE BUTTON
                        ========================================= */}

                        <Button
                            style={{
                                width: "100%"
                            }}
                            className="btn-sm"
                            type="submit"
                            variant="success"
                            disabled={loading}
                        >

                            {loading
                                ? "Saving..."
                                : "Save Address"
                            }

                        </Button>


                        {/* =========================================
                            CANCEL BUTTON
                        ========================================= */}

                        <Button
                            style={{
                                width: "100%"
                            }}
                            className="btn-sm mt-2"
                            variant="primary"
                            type="button"
                            onClick={toggleCreateAddress}
                        >

                            Cancel

                        </Button>


                    </Form>

                </Card.Body>

            </Card>

        </div>
    )
}


export default CreateAddressComponent
